-- A serial column added by `ADD COLUMN` is declared `NOT NULL`, as a `CREATE TABLE`'s is,
-- so it takes the identity clause once its default is dropped.
-- @setup
CREATE TABLE ais (v TEXT);
INSERT INTO ais VALUES ('a'), ('b');
ALTER TABLE ais ADD COLUMN id SERIAL;
ALTER TABLE ais ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE ais_id_seq;
ALTER TABLE ais ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 3);
INSERT INTO ais (v) VALUES ('c');
-- @test
SELECT id, v FROM ais ORDER BY id;
